package com.vahotel.web;
import com.vahotel.model.*;import com.vahotel.repo.*;import com.vahotel.service.*;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class CustomerController {private final AccountRepository accounts;private final RoomRepository rooms;private final ReservationRepository reservations;private final ReservationService service;private final PaymentService payment;private final CustomerReportRepository reports;
 public CustomerController(AccountRepository a,RoomRepository r,ReservationRepository b,ReservationService s,PaymentService p,CustomerReportRepository cr){accounts=a;rooms=r;reservations=b;service=s;payment=p;reports=cr;}
 @GetMapping("/customer/dashboard") public String dashboard(Authentication auth,Model m){Account a=accounts.findByEmail(auth.getName()).orElseThrow();m.addAttribute("reservations",reservations.findByCustomerIdOrderByCheckInDesc(a.getId()));m.addAttribute("rooms",rooms.findByActiveTrue());return "customer-dashboard";}
 @PostMapping("/customer/reservations") public String reserve(Authentication auth,@RequestParam Long roomId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Room r=rooms.findById(roomId).orElseThrow();Reservation booking=service.create(a,r,checkIn,checkOut);f.addFlashAttribute("message","Reservation created. Pay the 50% down payment now; the remaining balance is due later.");f.addFlashAttribute("reservationId",booking.getId());}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/pay") public String pay(Authentication auth,@PathVariable Long id,@RequestParam String method,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");BigDecimal due=r.getAmountPaid().signum()==0?r.getRequiredDownPayment():r.getTotalPrice().subtract(r.getAmountPaid());payment.simulatePayment(id,due,method);f.addFlashAttribute("message","Payment simulated and recorded. No real money was charged.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/cancel") public String cancel(Authentication auth,@PathVariable Long id,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"PENDING".equals(r.getStatus())&& !"PAID".equals(r.getStatus()) && !"APPROVED".equals(r.getStatus())){f.addFlashAttribute("error","This reservation cannot be cancelled from its current status.");}else{r.setStatusBeforeCancellation(r.getStatus());r.setStatus("CANCELLATION_REQUESTED");reservations.save(r);f.addFlashAttribute("message","Cancellation request sent to management. Refunds are not processed automatically.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reports") public String report(Authentication auth,@RequestParam String subject,@RequestParam String message,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();reports.save(new CustomerReport(a,subject,message));f.addFlashAttribute("message","Report submitted to hotel management.");return "redirect:/customer/dashboard";}

 @PostMapping("/customer/pencil-booking") public String pencilBooking(Authentication auth,@RequestParam Long roomId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Room room=rooms.findById(roomId).orElseThrow();Reservation b=service.create(a,room,checkIn,checkOut,"PENCIL");f.addFlashAttribute("message","Pencil booking request created. Management must review it before payment.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/early-checkout") public String earlyCheckout(Authentication auth,@PathVariable Long id,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"APPROVED".equals(r.getStatus())){f.addFlashAttribute("error","Only approved reservations can request early checkout.");}else{r.setEarlyCheckoutRequested(true);reservations.save(r);f.addFlashAttribute("message","Early checkout request sent to onsite management.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/extend") public String extend(Authentication auth,@PathVariable Long id,@RequestParam LocalDate newCheckOut,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"APPROVED".equals(r.getStatus())||!newCheckOut.isAfter(r.getCheckOut())){f.addFlashAttribute("error","Choose a later checkout date for an approved reservation.");}else{r.setRequestedCheckOut(newCheckOut);reservations.save(r);f.addFlashAttribute("message","Extension request sent to management.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/upgrade") public String upgrade(Authentication auth,@PathVariable Long id,@RequestParam Long roomId,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");Room target=rooms.findById(roomId).orElseThrow();if(!target.isActive()||target.getNightlyPrice().compareTo(r.getRoom().getNightlyPrice())<=0){f.addFlashAttribute("error","Choose an active room in a higher price category.");}else{r.setRequestedUpgradeRoomId(roomId);reservations.save(r);f.addFlashAttribute("message","Room upgrade request sent to management.");}return "redirect:/customer/dashboard";}
 @GetMapping("/customer/reservations/{id}/receipt") public String receipt(Authentication auth,@PathVariable Long id,Model m){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");m.addAttribute("reservation",r);return "receipt";}

}
